CREATE TABLE dbo.UserSession (
    SessionId INT NOT NULL,
    UserId INT NOT NULL,
    LoginTime DATETIME2 NOT NULL,
    CONSTRAINT PK_UserSession PRIMARY KEY NONCLUSTERED HASH (SessionId) WITH (BUCKET_COUNT = 1000000)
) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_AND_DATA);

CREATE TABLE dbo.UserSession2 (
    SessionId INT NOT NULL PRIMARY KEY NONCLUSTERED HASH WITH (BUCKET_COUNT = 1000000),
    UserId INT NOT NULL INDEX IX_UserId NONCLUSTERED HASH WITH (BUCKET_COUNT = 500000)
) WITH (MEMORY_OPTIMIZED = ON);

CREATE TABLE dbo.UserSession3 (
    SessionId INT NOT NULL,
    UserId INT NOT NULL,
    INDEX IX_UserSession_UserId NONCLUSTERED HASH (UserId) WITH (BUCKET_COUNT = 1000000),
    INDEX IX_UserSession_Hash HASH (SessionId) WITH (BUCKET_COUNT = 500000)
) WITH (MEMORY_OPTIMIZED = ON);

CREATE TABLE dbo.UserSession4 (
    SessionId INT NOT NULL,
    UserCode VARCHAR(50) NOT NULL,
    CONSTRAINT UQ_UserSession4 UNIQUE NONCLUSTERED HASH (UserCode) WITH (BUCKET_COUNT = 65536)
) WITH (MEMORY_OPTIMIZED = ON);
